def transform(grid):
    if not grid:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    vals = set()
    for r in range(rows):
        for c in range(cols):
            v = grid[r][c]
            if v != 0:
                vals.add(v)

    if not vals:
        return grid

    m = min(vals)
    M = max(vals)
    split_col = cols // 2

    result = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    for r in range(rows):
        row_nonzero = set(grid[r][c] for c in range(cols) if grid[r][c] != 0)

        has_m = (m in row_nonzero)
        has_M = (M in row_nonzero)

        if has_M and not has_m:
            # Has M only: uniform fill M-1 for zeros
            for c in range(cols):
                if grid[r][c] == 0:
                    result[r][c] = M - 1
        elif has_m and has_M:
            # Has both: uniform fill M-1 for zeros
            for c in range(cols):
                if grid[r][c] == 0:
                    result[r][c] = M - 1
        else:
            # Either has m only, or neither: split fill
            for c in range(cols):
                if grid[r][c] == 0:
                    if c < split_col:
                        result[r][c] = m
                    else:
                        result[r][c] = M - 1

    return result
