def transform(grid):
    if not grid:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # Find min and max non-zero
    non_zero = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0:
                non_zero.append(grid[r][c])

    if not non_zero:
        return grid

    m = min(non_zero)
    M = max(non_zero)
    split_col = cols // 2

    result = [[0]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
